mod.js:
morse.watch('section[aria-label="Comments"]', el => {
  el.classList.add('cm-collapsed');
  const h2 = el.querySelector(':scope > h2');
  const btn = morse.el('button', {
    class: 'cm-toggle',
    text: 'Show comments',
    style: 'font:inherit;font-size:14px;color:currentColor;background:transparent;border:1px solid rgb(162, 169, 177);border-radius:2px;padding:4px 10px;cursor:pointer;margin:0 0 8px',
    on: { click: () => {
      const open = el.classList.toggle('cm-collapsed') === false;
      btn.textContent = open ? 'Hide comments' : 'Show comments';
    } }
  });
  h2.after(btn);
});
